<div class="comm comm--<?= $h($channel); ?>" data-comm-mobile="<?= $mobile?'1':'0'; ?>" data-workspace="<?= $h($channel); ?>">
<div class="comm-crumb"><a href="<?= base_url('communications').($mobile?'?screen=mobile':''); ?>">Communications</a><span>/</span><span><?= $h($names[$channel]); ?></span></div>
<div class="comm-workspace">
<aside class="comm-rail" aria-label="<?= $h($names[$channel]); ?> workspace">
    <div class="comm-workspace-brand"><span class="comm-symbol"><?= $h($workspace_symbol); ?></span><div><b><?= $h($workspace_name); ?></b><small><?= $h($store_name); ?></small></div></div>
    <nav class="comm-local-nav" aria-label="<?= $h($names[$channel]); ?> pages">
    <?php foreach($workspace_menu as $section=>$label): ?><a class="<?= $workspace_section===$section?'active':''; ?>" <?= $workspace_section===$section?'aria-current="page"':''; ?> href="<?= $h($workspace_url($section)); ?>"><?= $h($label); ?><?php if($section==='campaigns' && $campaign_totals['drafts']): ?><span><?= (int)$campaign_totals['drafts']; ?> drafts</span><?php endif; ?></a><?php endforeach; ?>
    </nav>
    <div class="comm-rail-account"><span class="comm-badge <?= $m['active']?'ok':'off'; ?>"><?= !empty($workspace_inbox)?'Inbox':(!empty($workspace_development)?'Under development':(!$comm?'Status unavailable':($subscribed?'Subscribed':'Not subscribed'))); ?></span><?php if($wallet): ?><strong><?= number_format($wallet['balance_units']); ?></strong><small><?= $h($names[$channel]); ?> credits available</small><a href="<?= $h($workspace_url('recharge')); ?>">Recharge credits →</a><?php elseif(empty($workspace_development)): ?><a href="<?= $h($workspace_url('subscription')); ?>">Manage subscription →</a><?php endif; ?></div>
    <a class="comm-back-hub" href="<?= base_url('communications').($mobile?'?screen=mobile':''); ?>">‹ All communication channels</a>
</aside>
<section class="comm-workspace-main" aria-label="<?= $h($names[$channel]); ?> page">
<header class="comm-head"><div><span class="comm-eyebrow"><?= $h($workspace_name); ?></span><h1><?= $h($section_title); ?></h1><p class="muted"><?= $h($section_description); ?></p></div><?php if(!empty($section_action)): ?><a class="btn" href="<?= $h($workspace_url($section_action[0])); ?>"><?= $h($section_action[1]); ?></a><?php endif; ?></header>
<?php if(empty($workspace_development)): ?><div class="comm-account-line"><span class="comm-badge <?= $m['active']?'ok':'off'; ?>"><?= !$comm?'Status unavailable':($subscribed?'Subscribed':(!empty($m['subscribed_until'])?'Expired':'Not subscribed')); ?></span><?php if($expiry): ?><span>Expires <?= $h($expiry); ?></span><?php endif; ?><?php if($wallet): ?><span><b><?= number_format($wallet['balance_units']); ?></b> credits</span><a href="<?= $h($workspace_url('recharge')); ?>">Recharge</a><?php endif; ?><a href="<?= $h($workspace_url('subscription')); ?>">Subscription settings</a></div><?php endif; ?>
<?php foreach(array('success','failed') as $flash):if($text=$this->session->flashdata($flash)): ?><div role="status" class="notice <?= $flash==='failed'?'error':''; ?>"><?= $status_text($text); ?></div><?php endif;endforeach; ?>
<?php if(!$comm && empty($workspace_development)): ?><div class="notice"><?= $status_text($connection_message); ?></div><?php elseif($comm && empty($workspace_development) && (!$m['allowed'] || !$c['enabled'])): ?><div class="notice">Your Administrator has disabled this module. Contact your Administrator to request access.</div><?php elseif($comm && in_array($channel,array('email','sms'),true) && $m['active'] && empty($messaging['channels'][$channel])): ?><div class="notice">Your subscription is active, but sending is temporarily unavailable. Contact your Administrator.</div><?php endif; ?>

<?php if($channel==='automation' && !empty($comm['automation']['available']) && empty($comm['automation']['plan']['enabled'])): ?><div class="notice">Your Administrator has disabled your Automation plan. Existing workflows will remain paused until the plan is enabled or changed.</div><?php endif; ?>
